data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]
res = []
for i in range(n):
    dup = False
    for j in range(i):
        if a[j] == a[i]:
            dup = True
    if not dup:
        res.append(a[i])
out = []
for i in range(len(res) - 1, -1, -1):
    out.append(res[i])
print(' '.join(map(str, out)))

