def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([7]), fmt([5, 5, 5, 5]), fmt([1, 2, 3]), fmt([-3, 0, -3, 0]), fmt([10**9, -10**9, 10**9]), fmt([1, 2, 1, 2, 1, 2])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for hi in (3, 10, 1000):
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    n = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 1000) for _ in range(n)]))
    tests.append(fmt([7] * n))
    p = list(range(-50000, 50000))
    rng.shuffle(p)
    tests.append(fmt(p))
    return tests

